 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The demos map the enclosed cavity size to its fill color.
    fill_by_side = {3: 8, 5: 4, 7: 3}
    for r0 in range(h - 2):
        for r1 in range(r0 + 2, h):
            for c0 in range(w - 2):
                for c1 in range(c0 + 2, w):
                    if not (all(grid[r0][c] == 2 for c in range(c0, c1 + 1))
                            and all(grid[r1][c] == 2 for c in range(c0, c1 + 1))
                            and all(grid[r][c0] == 2 for r in range(r0, r1 + 1))
                            and all(grid[r][c1] == 2 for r in range(r0, r1 + 1))):
                        continue
                    inner_h, inner_w = r1 - r0 - 1, c1 - c0 - 1
                    if inner_h != inner_w or inner_h not in fill_by_side:
                        continue
                    center_r, center_c = (r0 + r1) // 2, (c0 + c1) // 2
                    if grid[center_r][center_c] != 2:
                        continue
                    if sum(grid[r][c] == 2
                           for r in range(r0 + 1, r1)
                           for c in range(c0 + 1, c1)) != 1:
                        continue
                    color = fill_by_side[inner_h]
                    for r in range(r0 + 1, r1):
                        for c in range(c0 + 1, c1):
                            if grid[r][c] == 0:
                                out[r][c] = color
    return out

